// QueryServer is the server API for Query service.
type QueryServer interface {
	// Params returns Hub parameters.
	Params(context.Context, *QueryHubParamsRequest) (*QueryHubParamsResponse, error)
	// Beacon returns one verified beacon by height.
	Beacon(context.Context, *QueryBeaconRequest) (*QueryBeaconResponse, error)
	// VrfKey returns one validator operator's active and pending VRF key.
	VrfKey(context.Context, *QueryVrfKeyRequest) (*QueryVrfKeyResponse, error)
	// BuilderSet returns one builder set selected by exactly one stable selector.
	BuilderSet(context.Context, *QueryBuilderSetRequest) (*QueryBuilderSetResponse, error)
	// Builder returns one builder identity.
	Builder(context.Context, *QueryBuilderRequest) (*QueryBuilderResponse, error)
	// Builders pages the whole builder registry. It is the only way to enumerate
	// builders: Query/Builder needs an address the caller already knows, so
	// without this RPC a fresh client cannot discover one. V1 takes no status
	// selector because BuilderState has no status index (api_contract §16.3).
	// Builders executes the Builders operation.
	Builders(context.Context, *QueryBuildersRequest) (*QueryBuildersResponse, error)
	// Fault returns one immutable role-fault attribution row.
	Fault(context.Context, *QueryFaultRequest) (*QueryFaultResponse, error)
	// Earnings returns one address earnings ledger.
	Earnings(context.Context, *QueryEarningsRequest) (*QueryEarningsResponse, error)
	// Model returns one registered model.
	Model(context.Context, *QueryModelRequest) (*QueryModelResponse, error)
	// Models pages the whole model registry. It is the only way to enumerate
	// models: Query/Model needs a model_id the caller already knows, so without
	// this RPC a fresh client cannot discover one. V1 takes no status selector
	// because ModelState has no status index (api_contract §16.3).
	// Models executes the Models operation.
	Models(context.Context, *QueryModelsRequest) (*QueryModelsResponse, error)
	// Profile returns one model profile.
	Profile(context.Context, *QueryProfileRequest) (*QueryProfileResponse, error)
	// CortexNode returns one stable service identity.
	CortexNode(context.Context, *QueryCortexNodeRequest) (*QueryCortexNodeResponse, error)
	// ServiceBond returns the node's single service bond and reserved liability.
	ServiceBond(context.Context, *QueryServiceBondRequest) (*QueryServiceBondResponse, error)
	// ServiceUnbondings pages one operator's unbonding entries by status.
	ServiceUnbondings(context.Context, *QueryServiceUnbondingsRequest) (*QueryServiceUnbondingsResponse, error)
	// CurrentServiceKey returns the sole current key binding for one operator,
	// including its ACTIVE or REVOKED lifecycle status.
	// CurrentServiceKey executes the CurrentServiceKey operation.
	CurrentServiceKey(context.Context, *QueryCurrentServiceKeyRequest) (*QueryCurrentServiceKeyResponse, error)
	// ServiceDescriptor returns one current bounded service descriptor.
	ServiceDescriptor(context.Context, *QueryServiceDescriptorRequest) (*QueryServiceDescriptorResponse, error)
	// ServiceLifecycle combines the identity and bond authorities of one operator.
	ServiceLifecycle(context.Context, *QueryServiceLifecycleRequest) (*QueryServiceLifecycleResponse, error)
	// ProfileCapability returns one operator/profile capability row.
	ProfileCapability(context.Context, *QueryProfileCapabilityRequest) (*QueryProfileCapabilityResponse, error)
	// ModelSupport returns one P30 support row.
	ModelSupport(context.Context, *QueryModelSupportRequest) (*QueryModelSupportResponse, error)
	// DailySupport returns one operator/epoch heartbeat row.
	DailySupport(context.Context, *QueryDailySupportRequest) (*QueryDailySupportResponse, error)
	// CurrentCandidatePool returns the single global pool the current pointer
	// resolves to (api_contract §16.3, empty request). Per-profile pools no longer
	// exist, so the old model_id/profile_version/duty path variables are gone.
	// CurrentCandidatePool executes the CurrentCandidatePool operation.
	CurrentCandidatePool(context.Context, *QueryCurrentCandidatePoolRequest) (*QueryCurrentCandidatePoolResponse, error)
	// CandidatePoolSnapshot returns a retained snapshot header by immutable ID.
	CandidatePoolSnapshot(context.Context, *QueryCandidatePoolSnapshotRequest) (*QueryCandidatePoolSnapshotResponse, error)
	// CandidatePoolMember returns one stable slot of one snapshot.
	CandidatePoolMember(context.Context, *QueryCandidatePoolMemberRequest) (*QueryCandidatePoolMemberResponse, error)
	// CandidatePoolMembers pages one snapshot's members in slot order.
	CandidatePoolMembers(context.Context, *QueryCandidatePoolMembersRequest) (*QueryCandidatePoolMembersResponse, error)
	// CompetitionEpoch returns one reward competition epoch.
	CompetitionEpoch(context.Context, *QueryCompetitionEpochRequest) (*QueryCompetitionEpochResponse, error)
	// RewardEpochCursor returns bounded reward processing progress.
	RewardEpochCursor(context.Context, *QueryRewardEpochCursorRequest) (*QueryRewardEpochCursorResponse, error)
	// RewardEpochAudit returns the immutable root retained after bounded prune.
	RewardEpochAudit(context.Context, *QueryRewardEpochAuditRequest) (*QueryRewardEpochAuditResponse, error)
	// Treasury returns the single treasury row.
	Treasury(context.Context, *QueryTreasuryRequest) (*QueryTreasuryResponse, error)
	// BridgeStatus returns the canonical route, controls, usage, supply, and live invariants.
	BridgeStatus(context.Context, *QueryBridgeStatusRequest) (*QueryBridgeStatusResponse, error)
	// ValidatorBridgeSigner returns one validator's registered bridge signer.
	ValidatorBridgeSigner(context.Context, *QueryValidatorBridgeSignerRequest) (*QueryValidatorBridgeSignerResponse, error)
	// FreezeSignal returns one retained freeze signal header.
	FreezeSignal(context.Context, *QueryFreezeSignalRequest) (*QueryFreezeSignalResponse, error)
	// FreezeSignals pages one profile's freeze signals; status is a closed enum.
	FreezeSignals(context.Context, *QueryFreezeSignalsRequest) (*QueryFreezeSignalsResponse, error)
	// EmergencyFreezeVotes lists votes for one signal.
	EmergencyFreezeVotes(context.Context, *QueryEmergencyFreezeVotesRequest) (*QueryEmergencyFreezeVotesResponse, error)
	// TimeoutBucket returns an exact or effective timeout bucket. The RPC moved
	// here from task.v1.Query with the governance writer (§2.4).
	// TimeoutBucket executes the TimeoutBucket operation.
	TimeoutBucket(context.Context, *QueryTimeoutBucketRequest) (*QueryTimeoutBucketResponse, error)
}

